  1→import { Head, router } from '@inertiajs/react';
  2→import {
  3→    Camera,
  4→    FlashlightOff,
  5→    Flashlight,
  6→    Lightbulb,
  7→    RefreshCw,
  8→    Search,
  9→    ScanSearch,
 10→    Sun,
 11→    Focus,
 12→    ScanLine,
 13→} from 'lucide-react';
