 20→    id: number;
 21→    crotal_code: string;
 22→    species: string;
 23→    breed: string;
 24→    sex: string;
 25→    name: string | null;
 26→    birth_date: string;
 27→    status: string;
 28→    sub_exploitation: {
 29→        id: number;
 30→        species: string;
 31→        exploitation_type: string;
