 48→function ScanInstructions({
 49→    onStart,
 50→    onManual,
 51→}: {
 52→    onStart: () => void;
 53→    onManual: () => void;
 54→}) {
 55→    const steps = [
 56→        {
 57→            icon: <Sun className="size-6 text-[#E53935]" />,
 58→            title: 'Buena iluminación y cobertura',
 59→            description:
 60→                'Asegúrate de estar en un lugar bien iluminado y con cobertura de señal móvil.',
 61→        },
 62→        {
 63→            icon: <Focus className="size-6 text-[#E53935]" />,
 64→            title: 'Enfoca el crotal',
 65→            description:
 66→                'Dirige la cámara hacia el crotal del animal, a unos 10-15 cm de distancia.',
 67→        },
 68→        {
 69→            icon: <ScanLine className="size-6 text-[#E53935]" />,
 70→            title: 'Espera al reconocimiento',
 71→            description:
