129→function CameraView({
130→    onResult,
131→    onError,
132→}: {
133→    onResult: (animal: AnimalResult) => void;
134→    onError: (lastDetected?: string) => void;
135→}) {
136→    const videoRef = useRef<HTMLVideoElement>(null);
137→    const srcCanvasRef = useRef<HTMLCanvasElement>(null);
138→    const procCanvasRef = useRef<HTMLCanvasElement>(null);
139→    const streamRef = useRef<MediaStream | null>(null);
140→    const [torch, setTorch] = useState(false);
141→    const [hasTorch, setHasTorch] = useState(false);
142→    const [statusText, setStatusText] = useState('Enfoca el crotal del animal');
143→    const [debugText, setDebugText] = useState('');
144→    const [showDebug, setShowDebug] = useState(false);
145→    const { recognizeFrame, isProcessing, terminate } = useCrotalOcr();
146→    const scanningRef = useRef(true);
147→    const onErrorRef = useRef(onError);
148→
149→    useEffect(() => {
150→        onErrorRef.current = onError;
151→    }, [onError]);
152→
153→    useEffect(() => {
154→        let cancelled = false;
155→
156→        (async () => {
157→            try {
158→                const stream = await navigator.mediaDevices.getUserMedia({
159→                    video: {
160→                        facingMode: 'environment',
161→                        width: { ideal: 1920 },
162→                        height: { ideal: 1080 },
163→                    },
164→                });
165→
166→                if (cancelled) {
167→                    stream.getTracks().forEach((t) => t.stop());
168→
169→                    return;
170→                }
171→
172→                streamRef.current = stream;
173→
174→                if (videoRef.current) {
175→                    videoRef.current.srcObject = stream;
176→                }
177→
178→                const track = stream.getVideoTracks()[0];
179→                const caps =
180→                    track.getCapabilities?.() as MediaTrackCapabilities & {
181→                        torch?: boolean;
182→                    };
183→
184→                if (caps?.torch) {
185→                    setHasTorch(true);
186→                }
187→            } catch {
188→                if (!cancelled) {
189→                    onErrorRef.current();
190→                }
191→            }
192→        })();
193→
194→        return () => {
195→            cancelled = true;
196→            scanningRef.current = false;
197→            streamRef.current?.getTracks().forEach((t) => t.stop());
198→            terminate();
199→        };
200→    }, [terminate]);
201→
202→    const toggleTorch = async () => {
203→        const track = streamRef.current?.getVideoTracks()[0];
204→
205→        if (track) {
206→            await track.applyConstraints({
207→                advanced: [{ torch: !torch } as MediaTrackConstraintSet],
208→            });
209→            setTorch(!torch);
210→        }
211→    };
212→
213→    const onResultRef = useRef(onResult);
214→
215→    useEffect(() => {
216→        onResultRef.current = onResult;
217→    }, [onResult]);
218→
219→    // Demo mock: simulate scanning and always resolve to a hardcoded crotal
220→    const DEMO_CROTAL = 'ES480151123456';
221→
222→    useEffect(() => {
223→        let active = true;
224→
225→        const mockScan = async () => {
226→            // Simulate scanning animation for 2 seconds
227→            setStatusText('Analizando...');
228→            await new Promise((r) => setTimeout(r, 2000));
229→
230→            if (!active || !scanningRef.current) {
231→                return;
232→            }
233→
234→            setDebugText(DEMO_CROTAL);
235→            scanningRef.current = false;
236→            setStatusText('Crotal detectado, buscando animal...');
237→
238→            try {
239→                const res = await fetch(
240→                    `/api/animals/by-crotal/${encodeURIComponent(DEMO_CROTAL)}`,
241→                );
242→
243→                if (res.ok) {
244→                    const animal = await res.json();
245→                    onResultRef.current(animal);
246→
247→                    return;
248→                }
249→            } catch {
250→                /* fall through */
251→            }
252→
253→            onErrorRef.current(DEMO_CROTAL);
254→        };
255→
256→        mockScan();
257→
258→        return () => {
259→            active = false;
260→        };
261→    }, []);
262→
263→    return (
264→        <div className="relative h-full w-full bg-[#1A1A1A]">
265→            <video
266→                ref={videoRef}
267→                autoPlay
268→                playsInline
269→                muted
270→                className="h-full w-full object-cover"
271→            />
272→            {/* Source canvas for full frame capture */}
273→            <canvas ref={srcCanvasRef} className="hidden" />
274→            {/* Processed canvas for binarized ROI — shown when debug is on */}
275→            <canvas
276→                ref={procCanvasRef}
277→                className={
278→                    showDebug
279→                        ? 'absolute bottom-20 left-2 z-50 h-24 w-40 border border-green-400'
280→                        : 'hidden'
281→                }
282→            />
283→
284→            <div className="absolute inset-0 flex items-center justify-center">
285→                <div className="relative h-48 w-72">
286→                    <div className="absolute inset-0 border-2 border-white/60" />
287→                    {isProcessing && (
288→                        <div className="absolute inset-x-0 top-0 h-0.5 animate-bounce bg-[#E53935]" />
289→                    )}
290→                </div>
291→            </div>
292→
293→            <div className="absolute inset-x-0 top-8 text-center">
294→                <p className="text-sm font-medium text-white/90">
295→                    {statusText}
296→                </p>
297→                {showDebug && debugText && (
298→                    <p className="mt-1 font-mono text-xs text-green-400">
299→                        OCR: {debugText}
300→                    </p>
301→                )}
302→            </div>
303→
304→            <div className="absolute inset-x-0 bottom-8 flex items-center justify-center gap-8">
305→                <button
306→                    onClick={() => setShowDebug((v) => !v)}
307→                    className="flex size-12 items-center justify-center bg-white/20 text-xs text-white"
308→                >
309→                    DBG
310→                </button>
311→                {hasTorch && (
312→                    <button
313→                        onClick={toggleTorch}
314→                        className="flex size-12 items-center justify-center bg-white/20 text-white"
315→                    >
316→                        {torch ? (
317→                            <Flashlight className="size-5" />
318→                        ) : (
319→                            <FlashlightOff className="size-5" />
320→                        )}
321→                    </button>
322→                )}
323→            </div>
324→        </div>
325→    );
326→}
