328→function AnimalResultCard({
329→    animal,
330→    onScanAgain,
331→}: {
332→    animal: AnimalResult;
333→    onScanAgain: () => void;
334→}) {
335→    const [age] = useState(() =>
336→        Math.floor(
337→            (Date.now() - new Date(animal.birth_date).getTime()) /
338→                (365.25 * 24 * 60 * 60 * 1000),
339→        ),
340→    );
341→
342→    return (
343→        <div className="flex flex-col gap-5 p-6">
344→            <div className="bg-[#E8F5E9] p-4 text-center">
345→                <p className="text-xs font-semibold text-[#2E7D32]">
346→                    Crotal identificado
347→                </p>
348→                <p className="mt-1 text-xl font-bold">{animal.crotal_code}</p>
349→            </div>
350→
351→            <div className="flex flex-col gap-3 border-2 border-black p-4">
352→                <div className="flex justify-between">
353→                    <span className="text-xs font-semibold tracking-[2px] text-[#757575] uppercase">
354→                        Ficha del animal
355→                    </span>
356→                    <span
357→                        className={`px-2 py-0.5 text-xs font-bold ${animal.status === 'active' ? 'bg-[#E8F5E9] text-[#2E7D32]' : 'bg-[#FFEBEE] text-[#E53935]'}`}
358→                    >
359→                        {animal.status === 'active' ? 'Activo' : animal.status}
