365→                        <p className="font-semibold capitalize">
366→                            {animal.species === 'bovine'
367→                                ? 'Bovino'
368→                                : animal.species === 'ovine'
369→                                  ? 'Ovino'
370→                                  : animal.species}
371→                        </p>
372→                    </div>
373→                    <div>
374→                        <p className="text-xs text-[#757575]">Raza</p>
375→                        <p className="font-semibold">{animal.breed}</p>
376→                    </div>
377→                    <div>
378→                        <p className="text-xs text-[#757575]">Sexo</p>
379→                        <p className="font-semibold">
380→                            {animal.sex === 'female' ? 'Hembra' : 'Macho'}
381→                        </p>
382→                    </div>
383→                    <div>
384→                        <p className="text-xs text-[#757575]">Edad</p>
385→                        <p className="font-semibold">{age} años</p>
386→                    </div>
387→                    {animal.name && (
388→                        <div className="col-span-2">
389→                            <p className="text-xs text-[#757575]">Nombre</p>
390→                            <p className="font-semibold">{animal.name}</p>
391→                        </div>
392→                    )}
393→                    <div className="col-span-2">
394→                        <p className="text-xs text-[#757575]">Subexplotación</p>
395→                        <p className="font-semibold capitalize">
396→                            {animal.sub_exploitation.exploitation_type}
397→                        </p>
398→                    </div>
399→                </div>
400→            </div>
401→
402→            <div className="flex flex-col gap-2">
403→                <button
404→                    onClick={onScanAgain}
405→                    className="w-full bg-[#E53935] py-[18px] text-center text-sm font-bold text-white"
406→                >
407→                    Escanear otro
408→                </button>
409→                <button
410→                    onClick={() => router.visit('/dashboard')}
411→                    className="w-full border-2 border-black py-[18px] text-center text-sm font-semibold"
412→                >
413→                    Volver al panel
414→                </button>
415→            </div>
416→        </div>
417→    );
418→}
