420→function ErrorView({
421→    onRetry,
422→    onResult,
423→    initialCode = '',
424→}: {
425→    onRetry: () => void;
426→    onResult: (animal: AnimalResult) => void;
427→    initialCode?: string;
428→}) {
429→    const [code, setCode] = useState(initialCode || 'ES');
430→    const [loading, setLoading] = useState(false);
431→    const [error, setError] = useState('');
432→
433→    const searchManual = async () => {
434→        const normalized = normalizeCrotalCode(code);
435→
436→        if (!normalized) {
437→            setError('Formato inválido. Debe ser ES + 12 dígitos');
438→
439→            return;
440→        }
441→
442→        setError('');
443→        setLoading(true);
444→
445→        try {
446→            const res = await fetch(
447→                `/api/animals/by-crotal/${encodeURIComponent(normalized)}`,
448→            );
449→
450→            if (res.ok) {
451→                onResult(await res.json());
452→            } else {
453→                setError('Animal no encontrado');
454→            }
455→        } catch {
456→            setError('Error de conexión');
457→        }
458→
459→        setLoading(false);
460→    };
461→
462→    return (
463→        <div className="flex flex-col gap-5 overflow-y-auto p-6">
464→            <div className="flex flex-col items-center gap-3">
465→                <div className="flex size-16 items-center justify-center rounded-full bg-[#FFF3E0]">
466→                    <ScanSearch className="size-8 text-[#E65100]" />
467→                </div>
468→                <h2 className="text-xl font-bold">No pude leer el crotal</h2>
469→                <p className="text-center text-sm text-[#757575]">
470→                    Inténtalo de nuevo o introduce el número manualmente
471→                </p>
472→            </div>
473→
474→            <button
475→                onClick={onRetry}
476→                className="flex w-full items-center justify-center gap-2 bg-[#E53935] py-[18px] text-sm font-bold text-white"
477→            >
478→                <RefreshCw className="size-4" />
479→                Intentar de nuevo
480→            </button>
481→
482→            <div className="flex flex-col gap-3 border-2 border-[#FFF8E1] bg-[#FFFDE7] p-4">
483→                <div className="flex items-center gap-2">
484→                    <Lightbulb className="size-5 text-[#F9A825]" />
485→                    <span className="text-sm font-bold">
486→                        Consejos para un mejor escaneo
487→                    </span>
488→                </div>
489→                <ul className="flex flex-col gap-2 text-xs text-[#757575]">
490→                    <li className="flex items-start gap-2">
491→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
492→                        Limpia el crotal con un trapo antes de escanear
493→                    </li>
494→                    <li className="flex items-start gap-2">
495→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
496→                        Acerca el móvil a 10-15 cm del crotal
497→                    </li>
498→                    <li className="flex items-start gap-2">
499→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
500→                        Busca buena iluminación, evita sombras sobre el crotal
501→                    </li>
502→                    <li className="flex items-start gap-2">
503→                        <span className="mt-0.5 size-1.5 shrink-0 rounded-full bg-[#F9A825]" />
504→                        Mantén el móvil firme y espera a que enfoque
505→                    </li>
506→                </ul>
507→            </div>
508→
509→            <div className="flex items-center gap-3">
510→                <div className="h-px flex-1 bg-[#E0E0E0]" />
511→                <span className="text-xs text-[#9E9E9E]">o</span>
512→                <div className="h-px flex-1 bg-[#E0E0E0]" />
513→            </div>
514→
515→            <div className="flex flex-col gap-3">
516→                <p className="text-xs font-semibold tracking-[2px] uppercase">
517→                    Ingresar manualmente
518→                </p>
519→                <div className="flex gap-2">
520→                    <input
521→                        type="text"
522→                        value={code}
523→                        onChange={(e) => setCode(e.target.value.toUpperCase())}
524→                        placeholder="ES480123456789"
525→                        className="h-[52px] flex-1 bg-[#F5F5F5] px-[18px] text-sm font-medium"
526→                        maxLength={14}
527→                    />
528→                    <button
529→                        onClick={searchManual}
530→                        disabled={code.length < 10 || loading}
531→                        className="flex h-[52px] w-[52px] items-center justify-center bg-[#E53935] text-white disabled:opacity-50"
532→                    >
533→                        <Search className="size-5" />
534→                    </button>
535→                </div>
536→                <p className="text-xs text-[#9E9E9E]">
537→                    Formato: ES + 4 dígitos provincia + 3 municipio + 5
538→                    individual
539→                </p>
540→                {error && (
541→                    <p className="text-sm font-medium text-[#E53935]">
542→                        {error}
543→                    </p>
544→                )}
545→            </div>
546→        </div>
547→    );
548→}
