550→function PermissionDenied({ onManual }: { onManual: () => void }) {
551→    return (
552→        <div className="flex flex-col items-center gap-5 p-6 pt-16">
553→            <Camera className="size-16 text-[#757575]" />
554→            <h2 className="text-xl font-bold">Acceso a cámara denegado</h2>
555→            <div className="flex flex-col gap-2 text-sm text-[#757575]">
556→                <p className="font-semibold text-black">
557→                    Para habilitar la cámara:
558→                </p>
559→                <p>iOS: Ajustes → Safari → Cámara → Permitir</p>
560→                <p>Android: Ajustes → Apps → Navegador → Permisos → Cámara</p>
561→            </div>
562→            <button
563→                onClick={onManual}
564→                className="w-full border-2 border-black py-[18px] text-center text-sm font-semibold"
565→            >
566→                Introducir código manualmente
567→            </button>
568→        </div>
569→    );
570→}
