572→export default function ScannerIndex() {
573→    const [state, setState] = useState<ScannerState>('instructions');
574→    const [animal, setAnimal] = useState<AnimalResult | null>(null);
575→    const [lastDetectedCode, setLastDetectedCode] = useState('');
576→
577→    const handleResult = (a: AnimalResult) => {
578→        setAnimal(a);
579→        setState('result');
580→    };
581→
582→    const handleError = (detected?: string) => {
583→        if (detected) {
584→            setLastDetectedCode(detected);
585→        }
586→
587→        setState('error');
588→    };
589→
590→    return (
591→        <AppLayout breadcrumbs={breadcrumbs}>
592→            <Head title="Escanear Crotal" />
593→            <div className="flex h-full flex-col">
594→                {state === 'instructions' && (
595→                    <ScanInstructions
596→                        onStart={() => setState('camera')}
597→                        onManual={() => setState('error')}
598→                    />
599→                )}
600→                {state === 'camera' && (
601→                    <div className="relative min-h-[500px] flex-1">
602→                        <CameraView
603→                            onResult={handleResult}
604→                            onError={(detected) => {
605→                                if (state === 'camera') {
606→                                    handleError(detected);
607→                                }
608→                            }}
609→                        />
610→                    </div>
611→                )}
612→                {state === 'result' && animal && (
613→                    <AnimalResultCard
614→                        animal={animal}
615→                        onScanAgain={() => {
616→                            setAnimal(null);
617→                            setState('camera');
618→                        }}
619→                    />
620→                )}
621→                {state === 'error' && (
622→                    <ErrorView
623→                        onRetry={() => setState('camera')}
624→                        onResult={handleResult}
625→                        initialCode={lastDetectedCode}
626→                    />
627→                )}
628→                {state === 'permission_denied' && (
629→                    <PermissionDenied onManual={() => setState('error')} />
630→                )}
631→
632→                {state === 'camera' && (
633→                    <div className="flex items-center justify-center border-t-2 border-black bg-white p-4">
634→                        <button
635→                            onClick={() => setState('error')}
636→                            className="text-sm font-semibold text-[#757575]"
637→                        >
638→                            Introducir código manualmente
639→                        </button>
640→                    </div>
641→                )}
642→            </div>
643→        </AppLayout>
644→    );
645→}
