519→export default function CrearNacimiento({ exploitation, success }: Props) {
520→    const [step, setStep] = useState(() => {
521→        if (success?.reference_code) return 5;
522→        return 0;
523→    });
524→    const [subExploitation, setSubExploitation] = useState<SubExploitation | null>(null);
525→    const [motherId, setMotherId] = useState<number | null>(null);
526→    const [fatherId, setFatherId] = useState<number | null>(null);
527→    const [calves, setCalves] = useState<CalfData[]>([]);
528→    const [submitting, setSubmitting] = useState(false);
529→    const [result, setResult] = useState<{ reference_code: string; calves: Array<{ name: string | null; sex: string; crotal: string }>; new_capacity: number; max_capacity: number } | null>(() => {
530→        if (success?.reference_code) {
531→            return {
532→                reference_code: success.reference_code,
533→                calves: success.calves || [],
534→                new_capacity: success.new_capacity || 0,
535→                max_capacity: 0,
536→            };
537→        }
538→        return null;
539→    });
540→
541→    const today = new Date().toISOString().split('T')[0];
542→
543→    const handleSubSelect = (sub: SubExploitation) => {
544→        setSubExploitation(sub);
545→        const motherBreed = sub.animals.find((a) => a.sex === 'female')?.breed || '';
546→        setCalves([{ sex: 'female', breed: motherBreed, name: '', birth_date: today }]);
547→        setStep(1);
548→    };
549→
550→    const handleMotherSelect = (id: number) => {
551→        setMotherId(id);
552→        const mother = subExploitation?.animals.find((a) => a.id === id);
553→        if (mother) {
554→            setCalves((prev) => prev.map((c) => ({ ...c, breed: mother.breed })));
555→        }
556→    };
557→
558→    const handleSubmit = () => {
559→        if (!subExploitation || !motherId) return;
560→        setSubmitting(true);
561→
562→        router.post('/nacimientos', {
563→            sub_exploitation_id: subExploitation.id,
564→            mother_id: motherId,
565→            father_id: fatherId,
566→            birth_type: calves.length > 1 ? 'multiple' : 'simple',
567→            calf_count: calves.length,
568→            calves: calves.map((c) => ({
569→                sex: c.sex,
570→                breed: c.breed,
571→                name: c.name || null,
572→                birth_date: c.birth_date,
573→            })),
574→        }, {
575→            onSuccess: (page) => {
576→                const successData = (page.props as any).success;
577→                if (successData) {
578→                    setResult({
579→                        reference_code: successData.reference_code,
580→                        calves: successData.calves || [],
581→                        new_capacity: successData.new_capacity || 0,
582→                        max_capacity: subExploitation.max_capacity,
583→                    });
584→                    setStep(5);
585→                }
586→            },
587→            onError: () => setSubmitting(false),
588→        });
589→    };
590→
591→    const canNext = () => {
592→        if (step === 0) return !!subExploitation;
593→        if (step === 1) return !!motherId;
594→        if (step === 3) return calves.every((c) => c.birth_date && c.sex && c.breed);
595→        return true;
596→    };
597→
598→    return (
599→        <AppLayout breadcrumbs={breadcrumbs}>

600→            <Head title="Comunicar Nacimiento" />
601→            <div className="flex flex-col gap-5 p-6">
602→                {step < 5 && (
603→                    <>
604→                        <ProgressBar currentStep={step} />
605→                        <p className="text-xs font-semibold uppercase tracking-[2px] text-[#757575]">Paso {step + 1} de 6</p>
606→                    </>
607→                )}
608→
609→                {step === 0 && !exploitation && (
610→                    <div className="flex flex-col items-center gap-4 py-12 text-center">
611→                        <Baby className="size-12 text-[#BDBDBD]" />
612→                        <h2 className="text-2xl font-bold">Sin explotación asignada</h2>
613→                        <p className="text-sm leading-[1.4] text-[#757575]">No tienes ninguna explotación asociada a tu cuenta. Contacta con tu administrador para que te asigne una.</p>
614→                        <button onClick={() => router.visit('/dashboard')} className="mt-2 border-2 border-black px-6 py-3 text-sm font-semibold">
615→                            Volver al panel
616→                        </button>
617→                    </div>
618→                )}
619→                {step === 0 && exploitation && <Step1 subExploitations={exploitation.sub_exploitations} onSelect={handleSubSelect} />}
620→                {step === 1 && subExploitation && <Step2 animals={subExploitation.animals} selectedId={motherId} onSelect={handleMotherSelect} />}
621→                {step === 2 && subExploitation && <Step3 animals={subExploitation.animals} selectedId={fatherId} onSelect={setFatherId} onSkip={() => { setFatherId(null); setStep(3); }} />}
622→                {step === 3 && subExploitation && (
623→                    <Step4
624→                        motherBreed={subExploitation.animals.find((a) => a.id === motherId)?.breed || ''}
625→                        calves={calves}
626→                        onUpdate={setCalves}
627→                    />
628→                )}
629→                {step === 4 && subExploitation && (
630→                    <Step5 sub={subExploitation} mother={motherId!} father={fatherId} calves={calves} animals={subExploitation.animals} onEditStep={setStep} />
631→                )}
632→                {step === 5 && result && <Step6 referenceCode={result.reference_code} calves={result.calves} newCapacity={result.new_capacity} maxCapacity={result.max_capacity} />}
633→
634→                {step > 0 && step < 5 && (
635→                    <div className="flex gap-2">
636→                        <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 border-2 border-black px-4 py-3 text-sm font-semibold">
637→                            <ChevronLeft className="size-4" /> Atrás
638→                        </button>
639→                        <div className="flex-1" />
640→                        {step < 4 ? (
641→                            <button
642→                                onClick={() => setStep(step + 1)}
643→                                disabled={!canNext()}
644→                                className="flex items-center gap-1 bg-[#E53935] px-6 py-3 text-sm font-bold text-white disabled:opacity-50"
645→                            >
646→                                Siguiente <ChevronRight className="size-4" />
647→                            </button>
648→                        ) : (
649→                            <button
650→                                onClick={handleSubmit}
651→                                disabled={submitting}
652→                                className="flex items-center gap-1 bg-[#E53935] px-6 py-3 text-sm font-bold text-white disabled:opacity-50"
653→                            >
654→                                {submitting ? 'Enviando...' : 'Enviar comunicación'}
655→                            </button>
656→                        )}
657→                    </div>
658→                )}
659→            </div>
660→        </AppLayout>
661→    );
662→}
