                            {maxCapacity - newCapacity} plazas libres
                        </span>
                    </div>
                    <div className="mt-2 h-1.5 w-full bg-[#F5F5F5]">
                        <div className={`h-1.5 ${newCapacity >= maxCapacity ? 'bg-[#E53935]' : 'bg-[#2E7D32]'}`} style={{ width: `${(newCapacity / maxCapacity) * 100}%` }} />
